import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.BaXgE4DV.js";const b=JSON.parse('{"title":"통계와 배지","description":"","frontmatter":{},"headers":[],"relativePath":"features/stats-badges.md","filePath":"features/stats-badges.md","lastUpdated":1791456149000}'),c={name:"features/stats-badges.md"};function r(s,t,i,l,n,u){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="통계와-배지" tabindex="-1">통계와 배지 <a class="header-anchor" href="#통계와-배지" aria-label="Permalink to &quot;통계와 배지&quot;">​</a></h1><p>연속일·월별 기록 수와 배지는 모두 <strong>서버에서</strong> 계산합니다. 클라이언트가 값을 조작할 수 없고, 기기 시간대와 상관없이 KST 기준으로 일관되게 계산하기 위해서입니다. → <a href="/grato-docs/decisions#adr-7">결정 기록 #7</a></p><h2 id="userstats" tabindex="-1">userStats <a class="header-anchor" href="#userstats" aria-label="Permalink to &quot;userStats&quot;">​</a></h2><p><code>userStats/{uid}</code>는 <code>onGratitudeCreated</code> 트리거의 첫 단계에서 갱신됩니다. 계산 로직은 Firebase에 의존하지 않는 순수 함수(<code>functions/src/utils/stats.ts</code>의 <code>computeNextStats</code>)라 단위 테스트로 검증합니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>의미</th></tr></thead><tbody><tr><td><code>totalGratos</code></td><td>전체 감사 수</td></tr><tr><td><code>currentStreak</code></td><td>마지막 기록일 기준 연속일</td></tr><tr><td><code>thisMonthCount</code></td><td><code>monthKey</code> 달의 감사 수</td></tr><tr><td><code>lastGratoDateKey</code></td><td>마지막 기록일 <code>YYYY-MM-DD</code> (KST)</td></tr><tr><td><code>monthKey</code></td><td><code>YYYY-MM</code> (KST)</td></tr><tr><td><code>lastGratoDate</code></td><td>마지막 기록 시각</td></tr></tbody></table><h3 id="계산-규칙-글-하나가-추가될-때" tabindex="-1">계산 규칙 (글 하나가 추가될 때) <a class="header-anchor" href="#계산-규칙-글-하나가-추가될-때" aria-label="Permalink to &quot;계산 규칙 (글 하나가 추가될 때)&quot;">​</a></h3><p>글의 <code>createdAt</code>을 KST 날짜 키로 바꿔 직전 기록일과 비교합니다.</p><table tabindex="0"><thead><tr><th>상황</th><th><code>currentStreak</code></th><th><code>thisMonthCount</code></th></tr></thead><tbody><tr><td>첫 기록</td><td>1</td><td>1</td></tr><tr><td>같은 날 또 기록</td><td>그대로</td><td>+1</td></tr><tr><td>바로 전날에 기록이 있었음</td><td>+1</td><td>같은 달이면 +1, 달이 바뀌었으면 1</td></tr><tr><td>하루 이상 비었음</td><td>1로 초기화</td><td>같은 달이면 +1, 아니면 1</td></tr><tr><td>더 오래된 글이 늦게 처리됨 (순서 뒤바뀜)</td><td>그대로</td><td>같은 달이면 +1</td></tr></tbody></table><ul><li><code>totalGratos</code>는 항상 +1입니다.</li><li>트리거 전달 순서가 뒤바뀌어도 마지막 기록일이 과거로 돌아가지 않습니다.</li><li><code>lastGratoDateKey</code>가 없는 예전 문서는 <code>lastGratoDate</code>에서 KST로 날짜를 계산합니다.</li><li>같은 트랜잭션에서 <code>statsLogs/gratitude_{id}</code> 마커를 만들어, 트리거가 두 번 실행돼도 한 번만 셉니다.</li><li>트리거가 실행되기 전에 글이 이미 지워졌으면 세지 않습니다.</li></ul><h3 id="rebuild" tabindex="-1">글을 지웠을 때 <a class="header-anchor" href="#rebuild" aria-label="Permalink to &quot;글을 지웠을 때 {#rebuild}&quot;">​</a></h3><p>글은 하나씩 빼는 대신 <strong>남은 글로 다시 계산합니다</strong>(<code>onGratitudeDeleted</code> → <code>rebuildUserStats</code>). 연속일 중간의 글을 지우면 연속일이 끊길 수 있어, 빼기만으로는 정확히 맞출 수 없기 때문입니다.</p><ul><li><code>totalGratos</code>는 남은 글 수(집계 <code>count()</code>), 나머지는 최근 글부터 읽은 KST 날짜로 계산합니다. 연속일과 최근 달을 넘어서는 날짜가 보일 때까지만 200개씩 읽습니다(최대 20쪽).</li><li>계산은 순수 함수 <code>statsFromDateKeys</code>·<code>dateKeysDecideStats</code>(<code>utils/stats.ts</code>)가 하고, 글을 하나씩 더한 결과와 같은지 단위 테스트로 확인합니다.</li><li><code>userStats</code> 문서가 있을 때만 고칩니다. 계정 삭제 뒤에 늦게 실행돼도 문서를 되살리지 않습니다.</li><li><strong>받은 배지는 유지합니다.</strong> 글을 지워 조건 아래로 내려가도 배지를 회수하지 않습니다.</li></ul><h3 id="화면-표시-규칙" tabindex="-1">화면 표시 규칙 <a class="header-anchor" href="#화면-표시-규칙" aria-label="Permalink to &quot;화면 표시 규칙&quot;">​</a></h3><p>저장된 <code>currentStreak</code>은 &quot;마지막으로 쓴 날 기준&quot; 값이라 오래 쓰지 않으면 낡은 값이 남습니다. 그래서 표시할 때 한 번 더 판단합니다(클라이언트 <code>getStatsView</code>, 서버 <code>displayStreak</code>).</p><table tabindex="0"><thead><tr><th>마지막 기록일 (KST)</th><th>표시 연속일</th><th>홈 카드 문구</th></tr></thead><tbody><tr><td>오늘</td><td>저장된 값</td><td>오늘도 감사를 기록했어요!</td></tr><tr><td>어제</td><td>저장된 값</td><td>어제도 감사했어요. 오늘도 이어가볼까요?</td></tr><tr><td>그 이전</td><td><strong>0</strong></td><td>감사 기록을 다시 시작해볼까요?</td></tr><tr><td>기록 없음</td><td>0</td><td>첫 번째 감사를 기록해보세요!</td></tr></tbody></table><ul><li><code>thisMonthCount</code>는 <code>monthKey</code>가 이번 달(KST)이 아니면 0으로 보여 줍니다.</li><li>방금 글을 쓴 세션에서는 트리거가 반영되기 전까지 <code>authStore.lastPostDateKey</code>로 오늘 기록을 미리 반영해 보여 줍니다.</li><li>홈과 MyPage는 <code>userStats</code>를 실시간 구독해 트리거 결과가 들어오면 바로 갱신됩니다.</li><li>공유 캘린더 페이지의 연속일도 서버에서 같은 규칙(<code>displayStreak</code>)으로 계산합니다.</li></ul><div class="info custom-block"><p class="custom-block-title">알려진 차이</p><p>MyPage 캘린더의 월 이동과 캘린더 공유 URL의 월은 아직 기기 시간대 기준입니다. 한국 밖에서 월 경계 근처에 보면 서버(KST)와 하루 차이가 날 수 있습니다.</p></div><h2 id="배지" tabindex="-1">배지 <a class="header-anchor" href="#배지" aria-label="Permalink to &quot;배지&quot;">​</a></h2><h3 id="기본-배지" tabindex="-1">기본 배지 <a class="header-anchor" href="#기본-배지" aria-label="Permalink to &quot;기본 배지&quot;">​</a></h3><p><code>badges</code> 컬렉션이 비어 있으면 첫 평가(또는 <code>seedQuestions</code> 스크립트) 때 기본 배지를 시드합니다. 비어 있지 않으면 건드리지 않으므로, 운영자가 지운 기본 배지는 다시 생기지 않습니다.</p><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>아이콘</th><th>조건</th></tr></thead><tbody><tr><td><code>gratitude_count_1</code></td><td>첫 감사</td><td>🌱</td><td>감사 1개</td></tr><tr><td><code>streak_3</code></td><td>3일 연속</td><td>🔥</td><td>연속 3일</td></tr><tr><td><code>streak_7</code></td><td>7일 연속</td><td>⚡</td><td>연속 7일</td></tr><tr><td><code>streak_30</code></td><td>30일 연속</td><td>💎</td><td>연속 30일</td></tr><tr><td><code>gratitude_count_10</code></td><td>감사 10개</td><td>🌿</td><td>감사 10개</td></tr><tr><td><code>gratitude_count_50</code></td><td>감사 50개</td><td>🌳</td><td>감사 50개</td></tr><tr><td><code>gratitude_count_100</code></td><td>감사 100개</td><td>🏆</td><td>감사 100개</td></tr><tr><td><code>circle_count_1</code></td><td>함께하기</td><td>🤝</td><td>Circle 1개 참여</td></tr></tbody></table><h3 id="question-badges" tabindex="-1">질문 배지 <a class="header-anchor" href="#question-badges" aria-label="Permalink to &quot;질문 배지 {#question-badges}&quot;">​</a></h3><p>제안한 질문이 운영자에게 선정되면 받는 단계별 배지입니다(1·3·10번째 선정). → <a href="/grato-docs/features/questions">질문 제안과 선정</a></p><ul><li>정의는 <code>functions/src/badges/questionBadges.ts</code>(<code>ensureQuestionBadges</code>)에 있습니다. 없는 배지만 배지 평가 때와 <code>seedQuestions</code> 스크립트가 만들고(<code>sortOrder</code>는 기존 배지 뒤), 이미 있는 문서는 운영자가 고친 내용을 덮어쓰지 않습니다.</li><li>이 셋은 지우면 다음 평가 때 다시 생기므로, 없애려면 <code>enabled: false</code>로 둡니다.</li><li>질문을 숨겨도 이미 받은 배지는 유지됩니다.</li></ul><table tabindex="0"><thead><tr><th>ID</th><th>이름</th><th>아이콘</th><th>설명</th></tr></thead><tbody><tr><td><code>questions_selected_1</code></td><td>첫 질문 선정</td><td>💡</td><td>제안한 질문이 처음으로 선정됐어요</td></tr><tr><td><code>questions_selected_3</code></td><td>질문 큐레이터</td><td>✨</td><td>제안한 질문이 3번 선정됐어요</td></tr><tr><td><code>questions_selected_10</code></td><td>질문 장인</td><td>🏅</td><td>제안한 질문이 10번 선정됐어요</td></tr></tbody></table><h3 id="조건-종류" tabindex="-1">조건 종류 <a class="header-anchor" href="#조건-종류" aria-label="Permalink to &quot;조건 종류&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>condition</code></th><th>비교 대상</th><th>계산 방법</th></tr></thead><tbody><tr><td><code>gratitude_count</code></td><td><code>userStats.totalGratos</code></td><td>통계 그대로</td></tr><tr><td><code>streak</code></td><td><code>userStats.currentStreak</code></td><td>통계 그대로</td></tr><tr><td><code>circle_count</code></td><td>실제로 멤버인 Circle 수</td><td><code>users.groupIds</code>의 각 그룹 문서를 읽어 <code>memberIds</code>에 있는 것만 셈. 글을 Circle에 공유했는지와는 상관없음</td></tr><tr><td><code>reactions_received</code></td><td>내 글들이 받은 리액션 합계</td><td>내 글 전체의 <code>reactions</code> 집계</td></tr><tr><td><code>shares</code></td><td>공개한 감사 글 수</td><td><code>userId == 나 &amp;&amp; isPublic == true</code> 개수 (count 집계)</td></tr><tr><td><code>questions_selected</code></td><td>선정된 질문 수</td><td><code>authorId == 나 &amp;&amp; source == &quot;user&quot; &amp;&amp; status == &quot;approved&quot;</code> 개수 (count 집계). 숨긴 질문은 세지 않지만 이미 받은 배지는 유지</td></tr></tbody></table><p>조건 판단은 순수 함수 <code>badges/conditions.ts</code>(<code>meetsBadgeCondition</code>)에 있습니다. 비용이 드는 계산(<code>circle_count</code>, <code>reactions_received</code>, <code>shares</code>, <code>questions_selected</code>)은 <strong>아직 얻지 않은 배지 중 그 조건이 있을 때만</strong> 실행합니다.</p><h3 id="평가-시점" tabindex="-1">평가 시점 <a class="header-anchor" href="#평가-시점" aria-label="Permalink to &quot;평가 시점&quot;">​</a></h3><table tabindex="0"><thead><tr><th>시점</th><th>함수</th></tr></thead><tbody><tr><td>글을 쓸 때 (통계 갱신 직후)</td><td><code>onGratitudeCreated</code> → <code>evaluateBadges(userId)</code></td></tr><tr><td>글을 처음 공개할 때 (<code>isPublic</code> false→true)</td><td><code>onReactionUpdated</code> → <code>evaluateBadges</code> (<code>shares</code> 조건)</td></tr><tr><td>Circle을 만들거나 새로 참여할 때</td><td><code>createCircle</code>, <code>joinCircle</code> → <code>evaluateBadges</code> (<code>circle_count</code> 조건)</td></tr><tr><td>제안한 질문이 선정될 때</td><td><code>reviewQuestion</code> → <code>evaluateBadges</code> (<code>questions_selected</code> 조건)</td></tr></tbody></table><p>리액션을 받는 것만으로는 평가하지 않으므로, <code>reactions_received</code> 배지는 다음 글을 쓸 때 부여됩니다.</p><h3 id="evaluatebadges-동작" tabindex="-1">evaluateBadges 동작 <a class="header-anchor" href="#evaluatebadges-동작" aria-label="Permalink to &quot;evaluateBadges 동작&quot;">​</a></h3><ol><li>기본 배지 시드(컬렉션이 비었을 때), 예전 배지 ID(<code>first_grato</code> 등)를 결정적 ID로 이전, 없는 질문 배지 생성</li><li><code>userStats</code>, <code>badges</code> 전체, <code>userBadges</code>, <code>users</code>를 병렬로 읽음</li><li><code>enabled !== false</code>이고 <code>startAt</code>~<code>endAt</code> 기간 안이며 아직 얻지 않은 배지만 후보</li><li>조건을 만족하는 배지를 트랜잭션으로 <code>userBadges.badges</code>에 <code>{badgeId, earnedAt}</code> 추가 — 트랜잭션 안에서 이미 가진 배지를 다시 확인해 동시 실행에도 중복 부여하지 않음. <code>users/{uid}</code>가 없으면(계정 삭제 중) 아무것도 쓰지 않음</li><li>새로 얻은 배지마다 <code>analyticsEvents</code>에 <code>badge_earned</code> 기록</li></ol><p><code>badges</code>를 조회할 때 <code>where(&#39;enabled&#39;, ...)</code>를 쓰지 않는 이유는 <code>enabled</code> 필드가 없는 문서가 쿼리에서 빠지기 때문입니다.</p><h2 id="배지-관리-관리자" tabindex="-1">배지 관리 (관리자) <a class="header-anchor" href="#배지-관리-관리자" aria-label="Permalink to &quot;배지 관리 (관리자)&quot;">​</a></h2><p><code>/admin</code> 페이지의 &quot;배지&quot; 탭에서 배지를 만들고 고칩니다(첫 탭은 <a href="/grato-docs/features/questions#review">질문 검토</a>). <code>users/{uid}.isAdmin == true</code>인 사용자만 내용이 보이고, 규칙도 같은 조건으로 <code>badges</code> 쓰기를 허용합니다. <code>isAdmin</code>은 Firebase 콘솔 또는 Admin SDK로만 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td>이름·설명·아이콘</td><td>표시 정보</td></tr><tr><td>조건·기준값</td><td>위의 6가지 조건 중 하나</td></tr><tr><td><code>badgeType</code></td><td>기본(<code>core</code>), 월간(<code>monthly</code>), 기간 한정(<code>limited</code>), 소셜(<code>social</code>)</td></tr><tr><td><code>seasonKey</code></td><td>시즌 구분 (기본 외 유형)</td></tr><tr><td><code>startAt</code>, <code>endAt</code></td><td>활성 기간 — 밖이면 평가·표시하지 않음</td></tr><tr><td><code>shareable</code></td><td>공유 가능 여부</td></tr><tr><td><code>enabled</code></td><td>끄면 평가·표시하지 않음</td></tr><tr><td><code>sortOrder</code></td><td>표시 순서 (위·아래 이동)</td></tr></tbody></table><ul><li>조건 선택지에 &quot;선정된 질문 수&quot;(<code>questions_selected</code>)가 있습니다.</li><li>새 배지의 문서 ID는 항상 <code>{condition}_{conditionValue}</code>입니다. 같은 조건·값의 배지가 이미 있으면 만들 수 없습니다.</li><li>이미 부여된 배지는 정의를 꺼도 <code>userBadges</code>에서 지워지지 않습니다.</li></ul><h2 id="배지-표시와-공유" tabindex="-1">배지 표시와 공유 <a class="header-anchor" href="#배지-표시와-공유" aria-label="Permalink to &quot;배지 표시와 공유&quot;">​</a></h2><p>MyPage 배지 카드는 얻은 배지를 먼저, 나머지를 흐리게 보여 주고 <code>얻은 수/전체 수</code>를 표시합니다. 배지를 누르면 상세 시트에서 획득일과 공유 버튼이 나옵니다. 공유하면 <code>publicShares/{uid}.badgeIds</code>에 추가되어 공유 페이지에 이름과 획득 여부가 보입니다. → <a href="/grato-docs/features/gratitudes#sharing">외부 공유</a></p>',40)])])}const g=d(c,[["render",r]]);export{b as __pageData,g as default};
